impl LearningIterationRuntimeBootstrapV1 {
    pub(crate) async fn wait_original_same_actor_evaluation_stage(
        &self,
        state: &AgentdState,
        snapshot: &LearningIterationSnapshotV1,
        stage: LearningIterationStageV1,
    ) -> Result<(), LearningIterationRuntimeErrorV1> {
        if stage != LearningIterationStageV1::Evaluation {
            return Ok(());
